//! The CrownOS system protocols, defined once for every app in the OS.
//!
//! Each submodule is generated by [`crate::protocol!`] and contains a typed
//! `Client`, a `Handler` trait for the serving side, a `dispatch` function
//! and the protocol's events. Because both ends come from the same
//! definition, client and server cannot drift apart.

mod compositor_proto;
mod crowncrate_proto;
mod crownotify_proto;
mod crownpad_proto;

pub use compositor_proto::compositor;
pub use crowncrate_proto::crowncrate;
pub use crownotify_proto::crownotify;
pub use crownpad_proto::crownpad;
